package cn.fixedblocks;
import java.util.*;
import java.io.*;
public class GameTest {
    static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
    static String legacySave(Game game){try{DataInputStream in=new DataInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(game.save())));ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);in.readInt();out.writeInt(1);for(int i=0;i<204;i++)out.writeInt(in.readInt());out.writeInt((int)in.readLong());while(in.available()>0)out.writeByte(in.readByte());return Base64.getEncoder().encodeToString(bytes.toByteArray());}catch(IOException e){throw new AssertionError(e);}}
    public static void main(String[] args){
        Game g=new Game();
        for(int t=0;t<7;t++)for(int r=0;r<4;r++){int count=0,n=Game.size(t);for(int y=0;y<n;y++)for(int x=0;x<n;x++)if(Game.cell(t,r,x,y))count++;check(count==4,"four cells in every rotation");}
        Set<Integer> bag=new HashSet<>();for(int i=0;i<7;i++){bag.add(g.type);while(!g.over&&g.y<18&&g.fits(g.type,g.rotation,g.x,g.y+1))g.tick();g.tick();}check(bag.size()==7,"seven-bag distribution");
        g.reset();int initial=g.y;g.tick();check(g.y==initial+1,"one cell per tick");g.score=100000;g.lines=900;initial=g.y;g.tick();check(g.y==initial+1&&Game.FALL_MS==700,"speed remains fixed at high scores");
        g.reset();for(int y=16;y<20;y++)Arrays.fill(g.board[y],1);g.board[15][4]=3;check(g.clearLines()==4,"four-line clear");check(g.score==800&&g.lines==4&&g.board[19][4]==3,"clear and shift rows");
        g.reset();g.type=0;g.rotation=1;g.x=-2;g.y=3;check(g.fits(0,1,-2,3),"vertical I at left wall");g.rotate();check(g.rotation==2&&g.fits(g.type,g.rotation,g.x,g.y),"I wall kick");
        g.reset();g.type=5;g.x=3;g.y=18;g.rotate();check(g.fits(g.type,g.rotation,g.x,g.y),"floor rotation remains valid");
        g.reset();g.type=6;g.x=0;g.y=18;g.tick();check(g.board[18][0]==7&&g.board[19][1]==7,"piece locks at floor");
        g.reset();g.type=6;g.x=3;g.y=-1;g.board[1][3]=1;g.tick();check(g.over,"top-out ends game");
        g.reset();g.move(-1);g.rotate();g.tick();String saved=g.save();Game other=new Game();other.restore(saved);check(saved.equals(other.save()),"save restores entire board and queue");
        g.reset();g.type=6;g.x=0;g.y=0;g.hardDrop();check(g.board[18][0]==7&&g.board[19][1]==7,"hard drop locks at floor and spawns next");
        g.reset();g.type=6;g.x=0;g.y=0;g.board[19][0]=1;g.hardDrop();check(g.board[17][0]==7&&g.board[18][1]==7&&g.board[19][0]==1,"hard drop stops above stack");
        g.reset();for(int i=2;i<10;i++)g.board[19][i]=1;g.type=6;g.x=0;g.y=0;g.hardDrop();check(g.lines==1&&g.score==100&&g.board[19][0]==7,"hard drop clears completed line");
        String end=g.save();g.over=true;String ended=g.save();g.hardDrop();check(ended.equals(g.save()),"hard drop disabled after game over");
        Game.Clock clock=new Game.Clock();check(!clock.update(999999),"initially paused");clock.start(1000,false);check(!clock.update(1699)&&clock.update(1700),"default speed");
        clock.pause();check(!clock.update(10000),"pause stops falling");clock.start(10000,true);check(clock.remaining(10000)==3&&!clock.active(),"resume shows three");check(!clock.update(11000)&&clock.remaining(11000)==2,"countdown two");check(!clock.update(12000)&&clock.remaining(12000)==1,"countdown one");check(!clock.update(13000)&&clock.active(),"countdown finishes without immediate fall");check(!clock.update(13699)&&clock.update(13700),"full fall interval after countdown");
        clock.start(20000,true);clock.pause();check(!clock.counting()&&!clock.update(25000),"background pause cancels countdown");
        for(int ms=100;ms<=2000;ms+=100){clock.setInterval(ms);clock.start(30000,false);check(!clock.update(30000+ms-1)&&clock.update(30000+ms),"all selectable speeds");}clock.setInterval(-1);check(clock.interval==100,"speed lower limit");clock.setInterval(9999);check(clock.interval==2000,"speed upper limit");clock.setInterval(400);clock.start(50000,false);clock.resetStep(50300);check(!clock.update(50699)&&clock.update(50700),"new piece gets full interval after hard drop");
        // Each finger owns its own hold: lifting rotation must not release horizontal movement.
        Game.InputTracker input=new Game.InputTracker();input.down(4,0,1000);input.down(9,1,1010);check(input.pressed(0)&&input.pressed(1),"simultaneous left and rotate are tracked independently");check(input.due(1249).length==0,"horizontal repeat waits for the initial delay");check(Arrays.equals(input.due(1250),new int[]{0}),"left repeats while rotation is held");input.up(9);check(input.pressed(0)&&!input.pressed(1),"lifting rotate leaves movement held");check(Arrays.equals(input.due(1335),new int[]{0}),"left continues after other finger lifts");input.down(6,3,1400);check(Arrays.equals(input.due(1450),new int[]{0,3}),"left and soft drop can repeat independently");input.up(4);check(input.pressed(3)&&!input.pressed(0),"lifting left leaves soft drop held");check(Arrays.equals(input.due(1500),new int[]{3}),"soft drop repeats on its own cadence");input.clear();check(input.pointers().length==0&&input.due(5000).length==0,"pause and cancellation clear all holds");
        // Projection must match the exact hard-drop landing without mutating state.
        for(int t=0;t<7;t++)for(int rotation=0;rotation<4;rotation++){g.reset();g.type=t;g.rotation=rotation;g.x=3;g.y=0;g.board[19][4]=2;String before=g.save();int landing=g.landingY();check(before.equals(g.save()),"ghost never changes board or queue");check(g.fits(t,rotation,g.x,landing)&&!g.fits(t,rotation,g.x,landing+1),"ghost stops exactly above floor or stack");int oldX=g.x;g.hardDrop();int n=Game.size(t);for(int j=0;j<n;j++)for(int i=0;i<n;i++)if(Game.cell(t,rotation,i,j))check(g.board[landing+j][oldX+i]==t+1,"ghost equals hard-drop placement");}
        g.reset();int oldY=g.y;g.softDrop();check(g.y==oldY+1,"soft drop moves exactly one row");g.type=6;g.x=0;g.y=18;g.softDrop();check(g.board[19][1]==7,"soft drop locks when blocked");
        g.reset();g.score=123400;g.lines=7;String legacy=legacySave(g);other.restore(legacy);check(g.save().equals(other.save()),"version 1 save migrates without losing queue or score");
        g.reset();g.score=2147483600L;Arrays.fill(g.board[19],1);g.clearLines();check(g.score==2147483700L,"score survives old integer limit");other.restore(g.save());check(other.score==g.score,"64-bit score persists");
        Game.Records records=new Game.Records();g.reset();records.startRound();records.startRound();check(records.games==1,"resume does not count another round");g.lines=3;g.score=500;records.sync(g);records.sync(g);check(records.totalLines==3&&records.best==500,"records never double-count lines");g.lines=5;records.newRound(g);check(records.totalLines==5&&records.best==500&&records.games==1,"restart preserves all accumulated results");records.startRound();check(records.games==2&&records.accountedLines==0,"new round counts once");g.lines=4;g.score=800;records.sync(g);Game.Records restored=new Game.Records();restored.best=records.best;restored.totalLines=records.totalLines;restored.games=records.games;restored.accountedLines=records.accountedLines;restored.roundCounted=records.roundCounted;other.restore(g.save());restored.sync(other);restored.startRound();check(restored.totalLines==9&&restored.games==2&&restored.best==800,"restoring a saved round never duplicates stats");g.lines=5;records.sync(g);check(records.totalLines==10,"newly cleared lines added after restore");
        // Simulate many complete games, checking collision and grid invariants.
        Random r=new Random(42);int locks=0;for(int i=0;i<40000;i++){if(g.over){g.reset();locks++;}if(r.nextBoolean())g.move(r.nextBoolean()?1:-1);if(r.nextInt(4)==0)g.rotate();g.tick();if(!g.over)check(g.fits(g.type,g.rotation,g.x,g.y),"active piece never overlaps");for(int[] row:g.board)for(int v:row)check(v>=0&&v<=7,"valid grid values");}check(locks>10,"long-running simulation");
        System.out.println("PASS: independent multitouch holds and repeat timing, 700ms default, all ghost rotations, soft/hard drops, records, legacy saves, all speeds, countdown, 40,000 simulated ticks.");
    }
}
